import{_ as n,o as s,c as e,a5 as p}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"53. 条件编译（#if、#ifdef、#ifndef）","description":"The Little Book of C 中文版 — 53. 条件编译（#if、#ifdef、#ifndef）","frontmatter":{"title":"53. 条件编译（#if、#ifdef、#ifndef）","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","06-编译与构建","中文"],"description":"The Little Book of C 中文版 — 53. 条件编译（#if、#ifdef、#ifndef）","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":53,"sidebarWeight":53,"alternateZh":"/posts/c教程/zh-CN/06-编译与构建/053-Conditional Compilation (if, ifdef, ifndef)","alternateEn":"/posts/c教程/en-US/06-Compilation and Build/053-Conditional Compilation (if, ifdef, ifndef)"},"headers":[],"relativePath":"posts/c教程/zh-CN/06-编译与构建/053-Conditional Compilation (if, ifdef, ifndef).md","filePath":"posts/c教程/zh-CN/06-编译与构建/053-Conditional Compilation (if, ifdef, ifndef).md","lastUpdated":1790163617000}'),i={name:"posts/c教程/zh-CN/06-编译与构建/053-Conditional Compilation (if, ifdef, ifndef).md"};function t(l,a,d,o,c,h){return s(),e("div",null,[...a[0]||(a[0]=[p(`<p>[English version](/posts/c教程/en-US/06-Compilation and Build/053-Conditional Compilation (if, ifdef, ifndef))</p><p>条件编译允许您控制编译哪些代码，不是在运行时，而是在编译时。这就是 C 程序如何适应不同的操作系统、体系结构或构建配置，而无需手动更改源文件。</p><p>将其视为仅编译器可见的逻辑。</p><h4 id="步骤-1-为什么存在条件编译" tabindex="-1">步骤 1. 为什么存在条件编译 <a class="header-anchor" href="#步骤-1-为什么存在条件编译" aria-label="Permalink to &quot;步骤 1. 为什么存在条件编译&quot;">​</a></h4><p>大型 C 程序通常需要处理差异，例如：</p><ul><li>平台（Windows、Linux、macOS、嵌入式）</li><li>编译器（gcc、clang、MSVC）</li><li>调试与发布版本</li><li>可选功能或实验模块</li></ul><p>您可以使用条件指令有选择地包含或排除代码，而不是维护同一文件的多个版本。</p><h4 id="步骤-2-核心指令" tabindex="-1">步骤 2. 核心指令 <a class="header-anchor" href="#步骤-2-核心指令" aria-label="Permalink to &quot;步骤 2. 核心指令&quot;">​</a></h4><table tabindex="0"><thead><tr><th>指令</th><th>目的</th></tr></thead><tbody><tr><td><code>#if </code></td><td>如果表达式为 true 则编译代码</td></tr><tr><td><code>#ifdef </code></td><td>如果定义了宏则编译</td></tr><tr><td><code>#ifndef </code></td><td>如果未定义宏则编译</td></tr><tr><td><code>#else</code></td><td>备用块</td></tr><tr><td><code>#elif </code></td><td>预处理器的 else-if</td></tr><tr><td><code>#endif</code></td><td>标记条件块的结束</td></tr></tbody></table><p>这些仅在编译开始之前的预处理期间起作用。</p><h4 id="小代码-特定于平台的编译" tabindex="-1">小代码：特定于平台的编译 <a class="header-anchor" href="#小代码-特定于平台的编译" aria-label="Permalink to &quot;小代码：特定于平台的编译&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>#ifdef _WIN32</span></span>
<span class="line"><span>    printf(&quot;Running on Windows\\n&quot;);</span></span>
<span class="line"><span>#elif __linux__</span></span>
<span class="line"><span>    printf(&quot;Running on Linux\\n&quot;);</span></span>
<span class="line"><span>#elif __APPLE__</span></span>
<span class="line"><span>    printf(&quot;Running on macOS\\n&quot;);</span></span>
<span class="line"><span>#else</span></span>
<span class="line"><span>    printf(&quot;Unknown platform\\n&quot;);</span></span>
<span class="line"><span>#endif</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在您的系统上编译并运行。输出将取决于编译器自动设置的预定义宏。</p><h4 id="步骤-3-启用和禁用功能" tabindex="-1">步骤 3. 启用和禁用功能 <a class="header-anchor" href="#步骤-3-启用和禁用功能" aria-label="Permalink to &quot;步骤 3. 启用和禁用功能&quot;">​</a></h4><p>您可以在编译时定义标志<code>-D</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -DDEBUG log.c -o log</span></span></code></pre></div><p>在你的代码中：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifdef DEBUG</span></span>
<span class="line"><span>    printf(&quot;Debug mode: extra checks enabled\\n&quot;);</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><p>切换无需重新编译，只需重新运行<code>gcc</code>有或没有<code>-DDEBUG</code>.</p><p>您还可以指定值：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -DVERSION=2 main.c -o main</span></span></code></pre></div><p>然后：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#if VERSION &gt;= 2</span></span>
<span class="line"><span>    printf(&quot;New feature enabled!\\n&quot;);</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><h4 id="步骤-4-使用-ifndef-保护代码" tabindex="-1">步骤 4. 使用 #ifndef 保护代码 <a class="header-anchor" href="#步骤-4-使用-ifndef-保护代码" aria-label="Permalink to &quot;步骤 4. 使用 #ifndef 保护代码&quot;">​</a></h4><p>这是 C 头文件中最常见的习惯用法之一：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifndef CONFIG_H</span></span>
<span class="line"><span>#define CONFIG_H</span></span>
<span class="line"><span>#define MAX_CLIENTS 100</span></span>
<span class="line"><span>#define TIMEOUT_MS 3000</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><p>它确保如果<code>config.h</code>被包含多次，它只被处理一次。 C 标准库中的每个头文件都使用此模式。</p><h4 id="步骤-5-排除实验代码" tabindex="-1">步骤 5. 排除实验代码 <a class="header-anchor" href="#步骤-5-排除实验代码" aria-label="Permalink to &quot;步骤 5. 排除实验代码&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define ENABLE_EXPERIMENTAL 0</span></span>
<span class="line"><span>#if ENABLE_EXPERIMENTAL</span></span>
<span class="line"><span>void experimental_feature() {</span></span>
<span class="line"><span>    printf(&quot;Running experimental feature\\n&quot;);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><p>如果<code>ENABLE_EXPERIMENTAL</code>设置为<code>0</code>，这段代码在编译之前就被完全删除了，它甚至不存在于目标文件中。</p><h4 id="小代码-调试模式示例" tabindex="-1">小代码：调试模式示例 <a class="header-anchor" href="#小代码-调试模式示例" aria-label="Permalink to &quot;小代码：调试模式示例&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#define DEBUG_MODE 1</span></span>
<span class="line"><span>void compute(int x) {</span></span>
<span class="line"><span>#if DEBUG_MODE</span></span>
<span class="line"><span>    printf(&quot;[DEBUG] compute() called with x=%d\\n&quot;, x);</span></span>
<span class="line"><span>#endif</span></span>
<span class="line"><span>    printf(&quot;Result: %d\\n&quot;, x * x);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    compute(5);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输出时<code>DEBUG_MODE</code>是 1：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[DEBUG] compute() called with x=5</span></span>
<span class="line"><span>Result: 25</span></span></code></pre></div><p>放<code>DEBUG_MODE</code>为0，重新编译，<code>[DEBUG]</code>消息完全消失。</p><h4 id="步骤-6-使用-elif-和-else" tabindex="-1">步骤 6. 使用 #elif 和 #else <a class="header-anchor" href="#步骤-6-使用-elif-和-else" aria-label="Permalink to &quot;步骤 6. 使用 #elif 和 #else&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define OS 2</span></span>
<span class="line"><span>#if OS == 1</span></span>
<span class="line"><span>    #define OS_NAME &quot;Windows&quot;</span></span>
<span class="line"><span>#elif OS == 2</span></span>
<span class="line"><span>    #define OS_NAME &quot;Linux&quot;</span></span>
<span class="line"><span>#else</span></span>
<span class="line"><span>    #define OS_NAME &quot;Unknown&quot;</span></span>
<span class="line"><span>#endif</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;OS: %s\\n&quot;, OS_NAME);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OS: Linux</span></span></code></pre></div><h4 id="步骤-7-与逻辑运算符组合" tabindex="-1">步骤 7. 与逻辑运算符组合 <a class="header-anchor" href="#步骤-7-与逻辑运算符组合" aria-label="Permalink to &quot;步骤 7. 与逻辑运算符组合&quot;">​</a></h4><p>您可以使用<code>&amp;&amp;</code>,<code>||</code>， 和<code>!</code>在预处理器条件下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#if defined(DEBUG) &amp;&amp; !defined(RELEASE)</span></span>
<span class="line"><span>    printf(&quot;Debug build only\\n&quot;);</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><p>您甚至可以使用数字比较：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#if VERSION &gt;= 3</span></span>
<span class="line"><span>    printf(&quot;Version 3+ detected\\n&quot;);</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><h4 id="步骤-8-强制编译错误" tabindex="-1">步骤 8. 强制编译错误 <a class="header-anchor" href="#步骤-8-强制编译错误" aria-label="Permalink to &quot;步骤 8. 强制编译错误&quot;">​</a></h4><p>有时，如果缺少所需的宏，您想停止编译：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifndef API_KEY</span></span>
<span class="line"><span>#error &quot;API_KEY not defined! Please compile with -DAPI_KEY=your_key&quot;</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><p>这对于构建时的配置验证很有用。</p><h4 id="步骤-9-编译器特定的宏" tabindex="-1">步骤 9. 编译器特定的宏 <a class="header-anchor" href="#步骤-9-编译器特定的宏" aria-label="Permalink to &quot;步骤 9. 编译器特定的宏&quot;">​</a></h4><p>编译器自动定义宏来识别自身和环境。</p><table tabindex="0"><thead><tr><th>宏</th><th>意义</th></tr></thead><tbody><tr><td><code>__GNUC__</code></td><td>由 GCC 定义</td></tr><tr><td><code>__clang__</code></td><td>由 Clang 定义</td></tr><tr><td><code>_MSC_VER</code></td><td>由 MSVC 定义</td></tr><tr><td><code>__x86_64__</code></td><td>64 位架构</td></tr><tr><td><code>__arm__</code>,<code>__aarch64__</code></td><td>ARM 架构</td></tr><tr><td><code>__STDC__</code></td><td>符合ANSI C标准</td></tr></tbody></table><p>您可以使用它们来编写可移植的自适应代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifdef __clang__</span></span>
<span class="line"><span>    printf(&quot;Compiled with Clang\\n&quot;);</span></span>
<span class="line"><span>#elif defined(__GNUC__)</span></span>
<span class="line"><span>    printf(&quot;Compiled with GCC\\n&quot;);</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><h4 id="小代码-便携式睡眠功能" tabindex="-1">小代码：便携式睡眠功能 <a class="header-anchor" href="#小代码-便携式睡眠功能" aria-label="Permalink to &quot;小代码：便携式睡眠功能&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#ifdef _WIN32</span></span>
<span class="line"><span>    #include &lt;windows.h&gt;</span></span>
<span class="line"><span>    #define SLEEP(ms) Sleep(ms)</span></span>
<span class="line"><span>#else</span></span>
<span class="line"><span>    #include &lt;unistd.h&gt;</span></span>
<span class="line"><span>    #define SLEEP(ms) usleep((ms) * 1000)</span></span>
<span class="line"><span>#endif</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;Waiting...\\n&quot;);</span></span>
<span class="line"><span>    SLEEP(1000);</span></span>
<span class="line"><span>    printf(&quot;Done!\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这可以在 Windows 和 Linux 上干净地编译，无需更改代码。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>条件编译使您的 C 代码：</p><ul><li>可移植，相同的代码可以在多个系统上运行</li><li>可配置，功能可以在构建时切换</li><li>可维护，不需要多个代码库</li><li>高效、排除的代码甚至不进入二进制文件</li></ul><p>在系统软件和嵌入式开发中，这是必不可少的。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>编写一个程序，根据操作系统打印不同的问候语。</li><li>使用<code>#if</code>和<code>#error</code>强制执行只有其中之一<code>DEBUG</code>或者<code>RELEASE</code>可以定义。</li><li>编写一个标头，定义不同CPU 架构的常量。</li><li>添加功能标志（<code>ENABLE_LOGGING</code>）可以通过以下方式打开/关闭<code>gcc -D</code>.</li><li>使用<code>#ifdef</code>和<code>#ifndef</code>创建一个轻量级的构建时配置系统。</li></ol><p>在下一节中，您将通过了解内联函数和标头卫生以及许多宏模式的现代、更安全的替代品，向干净、可维护的 C 代码迈出下一步。</p>`,63)])])}const f=n(i,[["render",t]]);export{u as __pageData,f as default};
